// Build Telegram caption: FA title + source + link (max ~1000 chars)
const inputItems = $input.all();

return inputItems.map(item => {
  const j = item.json;

  const titleFa = (j.title_fa || j.title || '').toString().trim();
  const link = (j.link || j.guid || '').toString().trim();

  let caption = titleFa;
  if (link) caption += `\n\nمنبع: SPIEGEL\n${link}`;

  if (caption.length > 1000) {
    if (link && !caption.endsWith(link)) {
      const roomForLink = 1 + link.length; // "\n" + link
      caption = caption.slice(0, Math.max(0, 1000 - roomForLink - 1)) + '…\n' + link;
    } else {
      caption = caption.slice(0, 1000);
    }
  }

  j.caption = caption;
  return item;
});

// Code node v2 — FULL RSS content minus ads (robust for non-<p> HTML)

const input = $input.all();

// Convert typical block-level HTML boundaries into paragraph breaks BEFORE stripping tags
function normalizeHtmlToParagraphText(html = '') {
  let s = String(html || '');

  // remove scripts/styles
  s = s.replace(/<script[\s\S]*?<\/script>/gi, ' ')
       .replace(/<style[\s\S]*?<\/style>/gi, ' ');

  // turn common block boundaries into paragraph breaks
  const blockBreaks = [
    'p','div','section','article','header','footer','aside',
    'h1','h2','h3','h4','h5','h6',
    'ul','ol','li',
    'blockquote',
    'table','tr',
  ];
  const blockRe = new RegExp(`</(?:${blockBreaks.join('|')})\\s*>`, 'gi');
  s = s.replace(blockRe, '\n\n');

  // <br> => line break
  s = s.replace(/<br\s*\/?>/gi, '\n');

  // strip remaining tags
  s = s.replace(/<[^>]*>/g, ' ');

  // whitespace cleanup
  s = s.replace(/[ \t]+\n/g, '\n')
       .replace(/\n[ \t]+/g, '\n')
       .replace(/[ \t]{2,}/g, ' ')
       .replace(/\n{3,}/g, '\n\n')
       .trim();

  return s;
}

// Werbung/CTA/Service-Teaser (erweiterbar)
function isAdParagraph(text = '') {
  const t = (text || '').toLowerCase().trim();
  if (!t) return false;

  const patterns = [
    /\banzeige\b/i,
    /\bsponsored\b/i,
    /\bwerbung\b/i,

    /jetzt\s+(abonnieren|registrieren|testen|kaufen|bestellen|downloaden)/i,
    /(hier|jetzt)\s+(weiterlesen|mehr\s+lesen|mehr\s+erfahren)/i,
    /\bmehr\s+dazu\b/i,

    /\bpodcast\b/i,
    /jetzt\s+(anhören|reinhören|hören)/i,
    /\bnewsletter\b/i,
    /\bapp\b/i,

    /\badvertisement\b/i,
    /\bsponsor(ed)?\b/i,
    /\bsubscribe\b/i,
    /\bdownload\b/i,
    /\btry\b/i,
  ];

  return patterns.some(re => re.test(t));
}

function fullContentWithoutAds(html = '') {
  const text = normalizeHtmlToParagraphText(html);
  if (!text) return '';

  // split into paragraph blocks
  const blocks = text
    .split(/\n{2,}/)
    .map(b => b.trim())
    .filter(Boolean);

  // remove ad blocks anywhere (CONTINUE)
  const kept = [];
  for (const b of blocks) {
    if (isAdParagraph(b)) continue;
    kept.push(b);
  }

  return kept.join('\n\n').trim();
}

return input.map(item => {
  const j = item.json || {};

  // imageUrl logic unchanged
  let image = (j.imageUrl || '').toString().trim();
  if (!image) {
    image =
      j.enclosure?.url ||
      j['media:content']?.url ||
      j['media:thumbnail']?.url ||
      j['media:group']?.['media:content']?.url ||
      j.thumbnail?.url ||
      j.image?.url ||
      j['itunes:image']?.href ||
      '';
  }

  // full text extraction
  const html = (j.content || j.summary || j.description || '');
  const cleaned = fullContentWithoutAds(html);

  item.json.imageUrl = image;
  item.json.teaser_de = cleaned || (j.content ?? j.summary ?? j.description ?? '');
  return item;
});

// Build Telegram payload (FULL RSS text, no truncation, multi-message chunks)
// - If real image exists: use caption (<=1024) + textChunks (<=4096 each)
// - If no real image: textChunks only
// Keeps RTL controls and clickable "منبع تصویر" only for REAL images.

const items = $input.all();

const esc = (s='') =>
  s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');

function hostFrom(link=''){
  const m = link.match(/^https?:\/\/([^\/?#]+)/i);
  return m ? m[1].replace(/^www\./,'') : '';
}

// RTL/LTR controls
const RLE = '\u202B', PDF = '\u202C', LRI = '\u2066', PDI = '\u2069';

const TELEGRAM_CAPTION_LIMIT = 1024;
const TELEGRAM_TEXT_LIMIT = 4096;

// Split text into chunks, preferring paragraph breaks, then sentence breaks, then hard split
function smartChunk(text, limit) {
  const clean = (text || '').toString().trim();
  if (!clean) return [];

  const paras = clean.split(/\n\s*\n/).map(s => s.trim()).filter(Boolean);
  const chunks = [];
  let buf = '';

  const flush = () => {
    if (buf.trim()) chunks.push(buf.trim());
    buf = '';
  };

  function pushHard(s) {
    for (let i = 0; i < s.length; i += limit) {
      chunks.push(s.slice(i, i + limit));
    }
  }

  function addUnit(unit, joiner) {
    if (!buf) {
      if (unit.length <= limit) buf = unit;
      else pushHard(unit);
      return;
    }
    const candidate = buf + joiner + unit;
    if (candidate.length <= limit) {
      buf = candidate;
    } else {
      flush();
      if (unit.length <= limit) buf = unit;
      else pushHard(unit);
    }
  }

  for (const p of paras) {
    if (p.length <= limit) {
      addUnit(p, '\n\n');
    } else {
      // paragraph too long -> split by sentences
      const sentences = p.split(/(?<=[\.\!\?؟])\s+/).map(s => s.trim()).filter(Boolean);
      for (const s of sentences) {
        if (s.length <= limit) addUnit(s, ' ');
        else {
          // sentence still too long -> hard split
          flush();
          pushHard(s);
        }
      }
    }
  }

  flush();
  return chunks.filter(Boolean);
}

// Wrap a chunk in RTL markers and enforce max length with ellipsis
function wrapRTLAndCap(s, max) {
  const core = (s || '').toString();
  // Reserve 1 char for ellipsis if we must cut
  const maxCore = Math.max(0, max);
  let trimmed = core;
  if (core.length > maxCore) {
    trimmed = core.slice(0, maxCore - 1) + '…';
  }
  return `${RLE}${trimmed}${PDF}`;
}

return items.map(i => {
  const j = i.json || {};

  const titleFa  = (j.title_fa  || j.title || '').toString().trim();
  const teaserFa = (j.teaser_fa || '').toString().trim();
  const link     = (j.link || j.guid || '').toString().trim();

  // Photo (may be real image or default logo later)
  let photo = (j.imageUrl || (j.telegram && j.telegram.photo) || '').toString().trim();

  // REAL image logic: only when RSS provided imageUrl
  const hasRealImage = !!(j.imageUrl && photo);

  // Image source line only for REAL image
  const imageLink = hasRealImage ? photo : '';
  const imageSourceLine = imageLink
    ? `📸 ${LRI}<a href="${esc(imageLink)}">منبع تصویر</a>${PDI}`
    : '';

  // Build the base body text (full, no truncate)
  // Keep title bold; put teaser after. Do NOT cap here; we chunk later.
  let body = `📰 <b>${esc(titleFa)}</b>`;
  if (teaserFa) body += `\n\n${esc(teaserFa)}`;

  // Link line (host as anchor text)
  if (link) {
    const host = hostFrom(link) || 'لینک خبر';
    const hostHtml = `${LRI}<a href="${esc(link)}">${esc(host)}</a>${PDI}`;
    body += `\n\n🔗 ${hostHtml}`;
  }

  const channelHandle = `${LRI}@German_news_fa${PDI}`;
  body += `\n\n${channelHandle}`;

  // If we have a REAL image, we want caption to start with imageSourceLine
  // and then the beginning of body, up to caption limit.
  let caption = '';
  let textChunks = [];

  if (hasRealImage) {
    let captionCore = '';
    if (imageSourceLine) captionCore += imageSourceLine + '\n\n';

    // We'll fill caption with as much of body as fits.
    // Because captionCore already has some length, we compute remaining.
    const remaining = TELEGRAM_CAPTION_LIMIT - (RLE.length + PDF.length) - captionCore.length;
    const bodyForCaption = remaining > 0 ? body.slice(0, remaining) : '';

    caption = wrapRTLAndCap(captionCore + bodyForCaption, TELEGRAM_CAPTION_LIMIT);

    // Now prepare the rest of the body after what we used in captionCore+bodyForCaption
    const usedBodyLen = bodyForCaption.length;
    const rest = body.slice(usedBodyLen).trim();

    // If rest still contains leading fragments, chunk it.
    textChunks = rest ? smartChunk(rest, TELEGRAM_TEXT_LIMIT) : [];
    // Wrap RTL and cap each chunk to 4096 safely
    textChunks = textChunks.map(c => wrapRTLAndCap(c, TELEGRAM_TEXT_LIMIT));
  } else {
    // No real image: everything is message chunks
    textChunks = smartChunk(body, TELEGRAM_TEXT_LIMIT).map(c => wrapRTLAndCap(c, TELEGRAM_TEXT_LIMIT));
  }

  // Inline button (safe JSON string)
  const replyMarkup = link
    ? JSON.stringify({ inline_keyboard: [[{ text: 'لینک خبر 🔗', url: link }]] })
    : undefined;

  return {
    json: {
      ...j,
      telegram: {
        photo,
        hasRealImage,
        caption,          // for Send Photo caption (only meaningful when hasRealImage)
        textChunks,       // array of messages to send after photo (or all messages if no image)
        replyMarkupJSON: replyMarkup
      }
    }
  };
});

