// keep only items newer than 15 minutes (aligned with cron)
const cutoff = Date.now() - 15 * 60 * 1000;
const out = [];

for (const item of $input.all()) {
  const j = item.json;
  const candidates = [j.isoDate, j.pubDate, j.date, j.pubdate];
  let pubDate = null;
  for (const c of candidates) {
    if (!c) continue;
    const d = new Date(c);
    if (!isNaN(d.getTime())) { pubDate = d; break; }
  }
  if (!pubDate) continue;                 // ⛔️ no date → skip
  if (pubDate.getTime() > cutoff) out.push(item);
}
return out;

// --- Persistent de-duplication across runs (with canonical link) ---
// Key = normalize(title) | host | (guid || canonical(link))

/** =================== CONFIG =================== **/
const TTL_HOURS = 72;                    // retain records for 48 hours
const RESET_MEMORY_ON_THIS_RUN = false;  // set true ONCE to clear memory
/** ============================================== **/

// 1) static memory
const staticData = $getWorkflowStaticData('global');
staticData.sent = staticData.sent || {}; // { hash: timestamp }

// optional reset
if (RESET_MEMORY_ON_THIS_RUN) {
  staticData.sent = {};
}

// 2) helpers (no DOM types; safe for n8n TS)
function normalize(s){ return (s||"").toLowerCase().replace(/\s+/g," ").trim(); }
function simpleHash(s){ let h=5381; for (let i=0;i<s.length;i++) h=((h<<5)+h)+s.charCodeAt(i); return (h>>>0).toString(16); }
function hostFrom(link=''){
  const m = (link||'').match(/^https?:\/\/([^\/?#]+)/i);
  return m ? m[1].replace(/^www\./,'') : '';
}
function canonicalizeLink(url=''){
  if (!url) return '';
  try {
    // n8n TS tip: avoid DOM types; use globalThis and cast to any
    const URLCtor = /** @type {any} */ (globalThis).URL;
    const u = new URLCtor(url);
    const drop = [
      'utm_source','utm_medium','utm_campaign','utm_term','utm_content','utm_id',
      'utm_reader','utm_name','utm_cid','utm_referrer','fbclid','gclid','igshid','mc_cid','mc_eid'
    ];
    drop.forEach(p => u.searchParams.delete(p));
    u.pathname = (u.pathname || '').replace(/\/+$/,''); // trim trailing slash
    u.protocol = 'https:'; // normalize protocol for key stability (optional)
    return u.toString();
  } catch {
    return url;
  }
}

// 3) TTL cleanup
const now = Date.now();
const TTL = TTL_HOURS * 60 * 60 * 1000;
for (const k of Object.keys(staticData.sent)) {
  if (now - staticData.sent[k] > TTL) delete staticData.sent[k];
}

// 4) main filtering
const items = $input.all();
const out = [];
let skipped = 0;

for (const it of items) {
  const j = it.json || {};
  const rawLink = (j.link || '').toString();
  const guid = (j.guid || j.id || '').toString();

  const canonLink = canonicalizeLink(rawLink);
  const host = j.sourceHost || hostFrom(canonLink) || '';
  const titleNorm = normalize(j.title || "");
  const stableId = guid || canonLink; // prefer guid

  const keyStr = [titleNorm, canonLink].join('|');
  const hash = simpleHash(keyStr);

  if (staticData.sent[hash]) { skipped++; continue; }

  staticData.sent[hash] = now;

  j._dedup_info = {
    ttl_hours: TTL_HOURS,
    memory_size: Object.keys(staticData.sent).length
  };

  out.push(it);
}

return out;

// Normalize + in-run dedupe + sort (with canonical link)
// Output fields: title, link, isoDate, pubDate, content, imageUrl, sourceHost, sourceFeed

const items = $input.all();

function toStr(v){ return (v ?? '').toString().trim(); }
function hostFrom(link=''){
  const m = link.match(/^https?:\/\/([^\/?#]+)/i);
  return m ? m[1].replace(/^www\./,'') : '';
}
function absolutize(url='', base=''){
  if (!url) return '';
  if (/^https?:\/\//i.test(url)) return url;
  if (url.startsWith('//')) return 'https:' + url;
  if (url.startsWith('/')) {
    const m = base.match(/^(https?:\/\/[^\/?#]+)/i);
    if (m) return m[1] + url;
  }
  return url;
}
function firstImgFromHtml(html=''){
  if (typeof html !== 'string') return '';
  const m = html.match(/<img[^>]+src=["']([^"']+)["']/i);
  return m?.[1] || '';
}
function canonicalizeLink(url=''){
  if (!url) return '';
  try {
    const u = new URL(url);
    // drop tracking params
    const drop = [
      'utm_source','utm_medium','utm_campaign','utm_term','utm_content','utm_id',
      'utm_reader','utm_name','utm_cid','utm_referrer','fbclid','gclid','igshid','mc_cid','mc_eid'
    ];
    drop.forEach(p => u.searchParams.delete(p));
    // normalize trailing slash
    u.pathname = u.pathname.replace(/\/+$/,'');
    // force https for stability (optional)
    u.protocol = 'https:';
    return u.toString();
  } catch {
    return url;
  }
}
function pickImage(j) {
  const mc = j['media:content'];
  if (mc) {
    if (Array.isArray(mc)) {
      const found = mc.find(x => x?.url);
      if (found?.url) return toStr(found.url);
    } else if (typeof mc === 'object' && mc.url) {
      return toStr(mc.url);
    }
  }
  const mt = j['media:thumbnail'];
  if (mt) {
    if (Array.isArray(mt)) {
      const found = mt.find(x => x?.url);
      if (found?.url) return toStr(found.url);
    } else if (typeof mt === 'object' && mt.url) {
      return toStr(mt.url);
    }
  }
  const mg = j['media:group'];
  if (mg?.['media:content']?.url) return toStr(mg['media:content'].url);

  if (j.enclosure?.url) return toStr(j.enclosure.url);

  if (j.image?.url) return toStr(j.image.url);
  if (j.thumbnail?.url) return toStr(j.thumbnail.url);
  if (j['itunes:image']?.href) return toStr(j['itunes:image'].href);

  const html = j['content:encoded'] || j.content || j.summary || j.description || '';
  const imgFromHtml = firstImgFromHtml(html);
  if (imgFromHtml) return toStr(imgFromHtml);

  return '';
}

const seen = new Set();
let out = [];

for (const it of items) {
  const j = it.json ?? {};
  const rawLink = toStr(j.link || j.guid);
  if (!rawLink) continue;

  const linkKey = canonicalizeLink(rawLink);
  if (!linkKey) continue;

  // in-run dedupe by canonical link
  if (seen.has(linkKey)) continue;
  seen.add(linkKey);

  // parse/normalize dates
  const rawDate = j.isoDate || j.pubDate || j.date || null;
  let iso = null, pub = null;
  if (rawDate) {
    const ts = Date.parse(rawDate);
    if (!Number.isNaN(ts)) {
      const d = new Date(ts);
      iso = d.toISOString();
      pub = d.toUTCString();
    }
  }

  // pick/normalize image
  let img = toStr(j.imageUrl) || pickImage(j);
  img = absolutize(img, linkKey);

  out.push({
    json: {
      sourceHost: hostFrom(linkKey) || hostFrom(j.feedUrl || ''),
      sourceFeed: j.feedTitle || j.meta?.title || j.source || '',
      title: toStr(j.title),
      link: linkKey,                  // ← use canonical link
      isoDate: iso,
      pubDate: pub,
      content: toStr(j.contentSnippet || j.summary || j.content || j['content:encoded'] || ''),
      imageUrl: img || '',
    },
  });
}

// newest first
out.sort((a,b) => {
  const ta = a.json.isoDate ? Date.parse(a.json.isoDate) : 0;
  const tb = b.json.isoDate ? Date.parse(b.json.isoDate) : 0;
  return tb - ta;
});

// cap list size if you want
const LIMIT = 5;
if (out.length > LIMIT) out = out.slice(0, LIMIT);

return out;

// Code node v2 — Similarity filter (cosine) with 70% threshold
// Input items must have: json.title, json.content (یا contentSnippet), json.isoDate, json.imageUrl
// Place this AFTER "Code (Normalize + Dedupe + Sort)" and BEFORE translation/posting.

// ====== CONFIG ======
const THRESHOLD = 0.40;           // 40%
const KEEP_MODE = 'imageFirst';       // 'newest' | 'longest' | 'imageFirst'
const MAX_ITEMS_COMPARE = 500;    // برای اطمینان از سرعت (در صورت نیاز کم/زیاد کن)
// =====================

const items = $input.all();
const n = Math.min(items.length, MAX_ITEMS_COMPARE);

// --- Helpers ---
function toStr(v){ return (v ?? '').toString(); }

// یک مجموعهٔ کوتاه از stopwordهای عمومی آلمانی/عمومی برای کاهش نویز
const STOP = new Set([
  'der','die','das','und','oder','aber','nicht','mit','für','auf','im','in','am','an','als','von','vom','den','dem',
  'ein','eine','einer','einem','eines','zu','zur','zum','ist','sind','war','waren','wird','werden','auch','noch',
  'the','a','an','of','to','for','on','in','at','by','from','it','this','that','be','as','are','was','were'
]);

function normalizeText(t) {
  return toStr(t)
    .toLowerCase()
    .replace(/<[^>]*>/g, ' ')          // حذف HTML ایمن
    .replace(/https?:\/\/\S+/g, ' ')   // حذف لینک‌ها
    .replace(/[^\p{L}\p{N}\s]+/gu, ' ')// حذف علائم
    .replace(/\s+/g, ' ')              // فشرده‌سازی فاصله‌ها
    .trim();
}

function tokenize(t) {
  const toks = normalizeText(t).split(' ');
  // حذف واژه‌های کوتاه و stopword ها
  return toks.filter(w => w.length > 2 && !STOP.has(w));
}

function tfVector(tokens) {
  const map = Object.create(null);
  for (const w of tokens) map[w] = (map[w] || 0) + 1;
  return map;
}

function cosineSim(vecA, vecB) {
  // dot
  let dot = 0;
  const keysA = Object.keys(vecA);
  for (const k of keysA) {
    if (vecB[k]) dot += vecA[k] * vecB[k];
  }
  // norms
  let normA = 0, normB = 0;
  for (const k of keysA) normA += vecA[k] * vecA[k];
  const keysB = Object.keys(vecB);
  for (const k of keysB) normB += vecB[k] * vecB[k];
  normA = Math.sqrt(normA);
  normB = Math.sqrt(normB);
  if (!normA || !normB) return 0;
  return dot / (normA * normB);
}

function pickText(j) {
  return [
    toStr(j.title),
    toStr(j.content || j.contentSnippet || j.summary || j['content:encoded'] || '')
  ].filter(Boolean).join(' — ');
}

function scoreItem(j) {
  const len = (toStr(j.content || j.contentSnippet || '').length);
  const hasImg = j.imageUrl ? 1 : 0;
  const ts = j.isoDate ? Date.parse(j.isoDate) || 0 : 0;

  if (KEEP_MODE === 'longest')   return (len) + hasImg * 100;
  if (KEEP_MODE === 'imageFirst')return hasImg * 1e9 + ts; // تصویر بشدت ارجح، سپس تازگی
  // default: newest
  return ts; // تازه‌ترین
}

// آماده‌سازی ویژگی‌ها
const data = [];
for (let i = 0; i < n; i++) {
  const it = items[i];
  const j = it.json || {};
  const text = pickText(j);
  const tokens = tokenize(text);
  const vec = tfVector(tokens);
  data.push({ index: i, item: it, json: j, vec, text });
}

// گروه‌بندی بر اساس شباهت
const used = new Array(n).fill(false);
const out = [];

for (let i = 0; i < n; i++) {
  if (used[i]) continue;

  // گروه جدید با آیتم i
  let group = [i];
  used[i] = true;

  for (let k = i + 1; k < n; k++) {
    if (used[k]) continue;
    const sim = cosineSim(data[i].vec, data[k].vec);
    if (sim >= THRESHOLD) {
      used[k] = true;
      group.push(k);
    }
  }

  // از گروه، یک آیتم را نگه می‌داریم بر اساس KEEP_MODE
  if (group.length === 1) {
    out.push(data[group[0]].item);
  } else {
    // بهترین را انتخاب کن
    let bestIdx = group[0];
    let bestScore = scoreItem(data[bestIdx].json);
    for (let t = 1; t < group.length; t++) {
      const cand = group[t];
      const s = scoreItem(data[cand].json);
      if (s > bestScore) {
        bestScore = s;
        bestIdx = cand;
      }
    }

    // برای شفافیت، متادیتای گروه را روی آیتم برنده می‌گذاریم
    const winner = data[bestIdx].item;
    const dupOf = group.filter(g => g !== bestIdx).map(g => ({
      link: data[g].json.link,
      title: data[g].json.title
    }));
    winner.json._similarity_group = {
      threshold: THRESHOLD,
      size: group.length,
      removed: dupOf
    };

    out.push(winner);
  }
}

