function normalizePunctuation(s=''){
  return s
    .replace(/ ,/g,'، ')
    .replace(/ ?\.\.\./g,'…')
    .replace(/\s*-\s*/g,' - ')
    .replace(/\s*:\s*/g,': ')
    .replace(/\s*؛\s*/g,'؛ ')
    .replace(/ ?! ?/g,'! ')
    .replace(/ \?/g,'؟ ')
    .replace(/\s+/g,' ')
    .replace(/\s+([»”\)\]])/g,'$1')
