const items = $input.all();
const staticData = $getWorkflowStaticData('global');

// تنظیمات
const DAILY_CAP = 12;            // حداکثر ۱۲ توییت در روز
const MIN_INTERVAL_MIN = 90;     // حداقل فاصلهٔ ۹۰ دقیقه بین توییت‌ها
const ACTIVE_HOURS = [7, 23];    // 07:00 تا 23:00 (Europe/Berlin)
const SCORE_THRESHOLD = 45;      // آستانهٔ امتیاز

// کلیدواژه‌های جغرافیایی
const kwIR_fa = /(ایران|تهران|اصفهان|شیراز|تبریز|اهواز|مجلس|سپاه|بانک مرکزی|انتخابات ایران|رئیس‌جمهور ایران)/;
const kwIR_de = /\b(Iran|Teheran|Tehran|Irans|iranisch)\b/i;
const kwME_fa = /(خاورمیانه|غزه|فلسطین|اسرائیل|لبنان|سوریه|عراق|یمن|بحرین|قطر|عمان|کویت|امارات|عربستان|اردن|مصر|ترکیه)/;
const kwME_de = /\b(Naher Osten|Gaza|Israel|Libanon|Syrien|Irak|Jemen|Bahrain|Katar|Oman|Kuwait|VAE|Saudi|Jordanien|Ägypten|Türkei|Palästina)\b/i;

function now(){ return new Date(); }
function sameDay(a,b){return a.getFullYear()===b.getFullYear()&&a.getMonth()===b.getMonth()&&a.getDate()===b.getDate();}
function hours(d){ return d.getHours()+d.getMinutes()/60; }

function hostWeight(h=''){
  h = h.replace(/^www\./,'').toLowerCase();
  if (/spiegel\.de$|tagesschau\.de$|faz\.net$|dw\.com$/.test(h)) return 40;
  if (/heise\.de$|golem\.de$|sueddeutsche\.de$|handelsblatt\.com$/.test(h)) return 30;
  return 15;
}
function topicBoost(t=''){
  t = (t||'').toLowerCase();
  if (/(ukraine|gaza|iran|wirtschaft|inflation|eu|usa|china|israel|\bki\b|künstliche)/i.test(t)) return 20;
  return 0;
}
function freshness(iso){
  if (!iso) return 0;
  const ts = Date.parse(iso); if (Number.isNaN(ts)) return 0;
  const ageMin = (Date.now()-ts)/60000;
  if (ageMin<=90) return 30;
  if (ageMin<=360) return 20;
  if (ageMin<=720) return 8;
  return 0;
}
function geoScore(j){
  const mix = [j.title_fa||'', j.teaser_fa||'', j.content||''].join(' ');
  if (kwIR_fa.test(mix) || kwIR_de.test(mix)) return {label:'iran',score:80};
  if (kwME_fa.test(mix) || kwME_de.test(mix)) return {label:'mena',score:50};
  return {label:'other',score:0};
}

// 🧹 فیلتر ۱: حذف پادکست‌ها
function isPodcast(j){
  const title   = (j.title_fa || j.title || '').toLowerCase();
  const teaser  = (j.teaser_fa || '').toLowerCase();
  const content = (j.content || '').toLowerCase();
  const link    = (j.link || '').toLowerCase();
  const all = [title, teaser, content, link].join(' ');

  const re = /(پادکست|پادکست خبری|پادکست SZ|podcast|podcasts|audio-podcast|audiopodcast|jetzt anhören|jetzt reinhören)/i;
  return re.test(all);
}

// 🧹 فیلتر ۲: خلاصه اخبار / چندخبره / تیکر / راؤنداپ
function isMultiNewsRoundup(j){
  const title   = (j.title_fa || j.title || '').toLowerCase();
  const teaser  = (j.teaser_fa || '').toLowerCase();
  const content = (j.content || '').toLowerCase();
  const link    = (j.link || '').toLowerCase();
  const all = [title, teaser, content, link].join(' ');

  const re = /(خلاصه اخبار روز|خلاصه اخبار|خبرهای کوتاه|مرور خبرها|جمع‌بندی خبرها|مرور روز|مرور امروز|ticker|liveticker|live-ticker|newsticker|transfer-ticker|transfer-ticker|im ticker|ticker:\s|ticker –|ticker -|ticker zu|kurzmeldungen|kurznews|im überblick|überblick|der tag kompakt|was heute wichtig ist|die lage am)/i;
  return re.test(all);
}

// 🧹 فیلتر ۳: بلاگ / وبلاگ
function isBlogLike(j){
  const title   = (j.title_fa || j.title || '').toLowerCase();
  const teaser  = (j.teaser_fa || '').toLowerCase();
  const content = (j.content || '').toLowerCase();
  const link    = (j.link || '').toLowerCase();
  const host    = (j.sourceHost || '').toLowerCase();
  const all = [title, teaser, content].join(' ');

  // blog در آدرس یا هاست
  if (/blog/.test(link) || /blog/.test(host)) return true;

  // ستون / نظر شخصی (اگر خواستی بعداً می‌تونیم دقیق‌تر کنیم)
  if (/(ستون|یادداشت|kolumne|kommentar|meinung)/i.test(all)) return true;

  return false;
}

// ساخت متن توییت
function buildTweetText(title, teaser, link) {
  const MAX = 280;

  // تمیز کردن متن
  const clean = (s = '') =>
    s.toString().replace(/\s+/g, ' ').trim();

  const t = clean(title);
  const p = clean(teaser);

  // تیتر + یک خط خالی + پاراگراف اول
  let base = t;
  if (p) base += (base ? '\n\n' : '') + p;

  // توییتر هر لینک را حدود ۲۳ کاراکتر حساب می‌کند (+ ۱ کاراکتر برای \n)
  const URL_RESERVED = 24; // 23 for t.co + '\n'
  const pad = link ? URL_RESERVED : 0;
  const room = MAX - pad;

  if (room <= 0) return link || '';

  if (base.length <= room) {
    return link ? `${base}\n${link}` : base;
  }

  // کوتاه کردن روی مرز کلمه
  const cut = base.slice(0, room - 1);
  let idx = cut.lastIndexOf(' ');
  if (idx < 40) idx = room - 1;
  const short = cut.slice(0, idx) + '…';

  return link ? `${short}\n${link}` : short;
}

// ریست روزانه
const n = now();
const lastReset = staticData.twitter_last_reset_ts ? new Date(staticData.twitter_last_reset_ts) : null;
if (!lastReset || !sameDay(n,lastReset)) {
  staticData.twitter_today_count = 0;
  staticData.twitter_last_reset_ts = n.toISOString();
}
const todayCount = staticData.twitter_today_count || 0;
const lastTs = staticData.last_tweet_ts ? new Date(staticData.last_tweet_ts) : null;
const sinceMin = lastTs ? (n-lastTs)/60000 : Infinity;
const inHours = (() => {
  const h = hours(n);
  return h >= ACTIVE_HOURS[0] && h <= ACTIVE_HOURS[1];
})();

return items.map(it => {
  const j = it.json || {};
  const link   = (j.link || '').toString().trim();
  const title  = (j.title_fa || j.title || '').toString().trim();
  const teaser = (j.teaser_fa || '').toString().trim();

  const geo = geoScore(j);
  let score = 0;
  score += hostWeight(j.sourceHost || '');
  score += topicBoost(title);
  score += freshness(j.isoDate || '');
  score += geo.score;

  // 🧱 دلایل حذف (برای دیباگ)
  const reasons = [];
  if (isPodcast(j))      reasons.push('podcast');
  if (isMultiNewsRoundup(j)) reasons.push('multi_news_roundup');
  if (isBlogLike(j))     reasons.push('blog_like');

  const filteredOut = reasons.length > 0;

  if (filteredOut) {
    // اگر دوست داشته باشی، می‌تونیم score را هم صفر کنیم
    score = 0;
  }

  const ok =
    (score >= SCORE_THRESHOLD) &&
    (todayCount < DAILY_CAP) &&
    (sinceMin >= MIN_INTERVAL_MIN) &&
    inHours &&
    !filteredOut;

  const okBool = !!ok;

  it.json.twitter = {
    ok: okBool,
    score,
    geo: geo.label,
    filteredOut,
    filteredReasons: reasons,
    text: buildTweetText(title, teaser, link),
  };

  return it;
});

